// getJsonData retrieves and parses JSON data from a specified HTML element
VariationTable.getJsonData = function (elementId) {
    var element = document.getElementById(elementId);
    if (!element) {
        return null;
    }
    try {
        return JSON.parse(element.textContent);
    } catch (e) {
        return null;
    }
};

// processColumns processes the columns configuration to attach render functions
VariationTable.processColumns = function (columnsConfig) {
    var self = this;
    var storedColumnNames = self.loadColumnsFromStorage();
    var visibleColumnNames = storedColumnNames && storedColumnNames.length > 0
        ? storedColumnNames
        : self.defaultColumnNames;

    return columnsConfig.map(function (col) {
        var key = col.name || col.data;
        col.visible = visibleColumnNames.indexOf(key) !== -1;

        if (col.render_type) {
            if (self.renderFunctions[col.render_type]) {
                col.render = self.renderFunctions[col.render_type];
            }
            delete col.render_type;
        }

        if (col.orderable === false || col.orderable === 'False') {
            col.orderable = false;
        } else if (col.orderable === true || col.orderable === 'True') {
            col.orderable = true;
        }
        // default to non-orderable
        else if (col.orderable === undefined) {
            col.orderable = false;
        }

        return col;
    });
};

// ********************************
// Task 1. Columns Sorting
// ********************************
VariationTable.initSortSelect = function () {
    var _this = this;
    $('#sort-select').on('change', function (e) {
        // GA tracking for sorting change
        ncbi.pinger.ping(this, e, 'click_on', {
            ga_category: 'table_controls',
            ga_action: 'click_on',
            ga_label: 'sort by ' + $(this).val().toLowerCase()
        });
        _this.rebuildAll()
    });
};


// ********************************
// Task 2. Column Management Modal
// ********************************
// saveColumnsToStorage saves the current column configuration to local storage
VariationTable.saveColumnsToStorage = function () {
    var visibleColumnNames = [];
    VariationTable.allColumns.forEach(function (col, index) {
        if (VariationTable.table.column(index).visible()) {
            visibleColumnNames.push(col.name || col.data);
        }
    });
    localStorage.setItem('tableColumns', JSON.stringify(visibleColumnNames));
};

// loadColumnsFromStorage loads the column configuration from local storage
VariationTable.loadColumnsFromStorage = function () {
    var stored = localStorage.getItem('tableColumns');
    if (stored) {
        try {
            return JSON.parse(stored);
        } catch (e) {
            console.error('Failed to parse column configuration:', e);
        }
    }
    return null;
};

// renderColumnModal renders the content of the column management modal
VariationTable.renderColumnModal = function () {
    $('.col-checkbox').each(function () {
        var colName = $(this).val();
        var colIndex = VariationTable.allColumns.findIndex(function (col) {
            return (col.name || col.data) === colName;
        });
        var isVisible = colIndex !== -1 && VariationTable.table.column(colIndex).visible();
        $(this).prop('checked', isVisible);
    });
};


// ********************************
// Task 3. Custom Search Box
// ********************************
VariationTable.getTotalCount = function () {
    var meta = this.getJsonData('meta-json');
    if (meta && meta.total_count) {
        return meta.total_count;
    }
    return null;
}

// updateFilterCounts updates the counts displayed next to each filter option
// based on the provided filter groups data
VariationTable.updateFilterCounts = function (filterGroups, conflictsCount) {
    if (conflictsCount == 0) {
        $('div[id="Types of conflicts"').hide();
    } else {
        $('div[id="Types of conflicts"').show();
    }

    filterGroups.forEach(function (group) {
        group.filters.forEach(function (f) {
            $('span[data-filter="' + f.FilterName + '"]')
                .text('(' + Number(f.Count).toLocaleString() + ')');
        });
    });
};

// ********************************
// Final Step. Initialization and Rendering
// ******************************** 

// initPagination sets up the pagination controls and their event handlers 
VariationTable.initPagination = function () {
    var self = this;


    function draw_page(which)
    {
      fixed_x_scrollbar.resetAll();
      AfterRender.init_uids();
      self.table.page(which).draw('page');
      setTimeout(
        function()
        {
          AfterRender.update_table();
        }, 100);
    }

    this.table.on('draw.dt', function () {
        var info = self.table.page.info();
        var currentPage = info.page + 1;        // DataTables uses 0-based index for pages, so add 1 for display
        var totalPages = info.pages;

        $(VariationTable.selectorPage).val(currentPage).attr('max', totalPages);
        $('.page-total').text(totalPages);
        $('.btn-prev').prop('disabled', currentPage <= 1);
        $('.btn-next').prop('disabled', currentPage >= totalPages);
    });

    function handle_prev_next(elem, incr)
    {
      var jq = jQuery(elem).closest('.pagination').find(VariationTable.selectorPage);
      if(!jq.length)
      {
        jq = jQuery(VariationTable.selectorPage);
      }
      if(jq.length)
      {
        var v = parseInt(jq.val());
        if (!isNaN(v))
        {
          v += incr;
          jQuery(VariationTable.selectorPage).val(String(v));
        }
        jQuery(jq[0]).trigger("change");
      }
    }

    // prev/next button click handlers
    // 7/20/26 draw_page('next') stopped working
    // after adding pagination below the table
    $('.btn-prev').on('click', function () {
        handle_prev_next(this, -1);
    });
    $('.btn-next').on('click', function () {
        handle_prev_next(this, 1);
    });

    // page input change handler with debounce
    $(VariationTable.selectorPage).on('change', function () {

        function scrollToTop()
        {
          window.scrollTo(0, 0);
        }
        jQuery(this).closest('.nav-bottom').length && setTimeout(scrollToTop, 100);

        var v = parseInt($(this).val());
        if (isNaN(v))
        {
            alert('Please enter a page number');
            $(VariationTable.selectorPage).val(self.table.page.info().page + 1);
            return;
        }
        v = parseInt(v);
        var totalPages = self.table.page.info().pages;
        v = Math.max(1, Math.min(totalPages, v));
        $(VariationTable.selectorPage).val(v);
        draw_page(v - 1);  // DataTables uses 0-based index for pages
    });
    $(VariationTable.selectorPage).on('keydown', function (e) {
        if (e.key === 'Enter') $(this).trigger('change');
    });
}

// init initializes the VariationTable by loading data and setting up columns
VariationTable.init = function () {
    this.defaultColumnNames = this.getJsonData('default-columns');
    let columnsConfig = this.getJsonData('all-columns');
    this.allColumns = this.processColumns(columnsConfig);
    this.render();
};

